#include <cstdio>
#include <vector>
#include <algorithm>
#include <random>

void quickSort(std::vector<long long>& a, int l, int r) {
    if (l >= r) return;
    // 三数取中，避免有序数据退化
    int mid = l + (r - l) / 2;
    long long p; 
    if ((a[l] <= a[mid] && a[mid] <= a[r]) || (a[r] <= a[mid] && a[mid] <= a[l])) p = a[mid];
    else if ((a[mid] <= a[l] && a[l] <= a[r]) || (a[r] <= a[l] && a[l] <= a[mid])) p = a[l];
    else p = a[r];

    int i = l, j = r;
    while (i <= j) {
        while (a[i] < p) ++i;
        while (a[j] > p) --j;
        if (i <= j) { std::swap(a[i], a[j]); ++i; --j; }
    }
    quickSort(a, l, j);
    quickSort(a, i, r);
}

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    quickSort(a, 0, n - 1);

    for (int i = 0; i < n; ++i) {
        if (i) printf(" ");
        printf("%lld", a[i]);
    }
    printf("\n");
    return 0;
}
